// Some portions generated by Co-Pilot
"use client";

import React, { useMemo, useSyncExternalStore } from "react";
import { Link } from "@/i18n/navigation";
import { sendDownloadEvent } from "@/utils/gtag";
import { useTranslations } from "next-intl";
import { detectOS, UserOS } from "@/utils/detectOS";
import { useFetchLatestForOS } from "@/hooks";
import OSIcon from "./OSIcon";
import { FiDownload, FiArrowRight } from "react-icons/fi";

const subscribe = () => () => {};
const getServerOS = () => UserOS.UNKNOWN;

interface DownloadButtonProps {
  latestLTS: number;
}

const DownloadButton: React.FC<DownloadButtonProps> = ({ latestLTS }) => {
  const t = useTranslations("HomePage");
  const userOS = useSyncExternalStore(subscribe, detectOS, getServerOS);
  const { name, apiName, arch } = useMemo(() => {
    let arch = "x64";
    switch (userOS) {
      case UserOS.MAC: {
        const gl = document.createElement("canvas").getContext("webgl");
        const extension = gl?.getExtension("WEBGL_debug_renderer_info");
        const renderer: string = extension
          ? gl?.getParameter(extension.UNMASKED_RENDERER_WEBGL) || ""
          : "";
        const isSafari = /^((?!chrome|android).)*safari/i.test(
          navigator.userAgent,
        );
        if (
          isSafari ||
          (renderer.includes("Apple") && !renderer.includes("Apple GPU"))
        ) {
          arch = "aarch64";
        }
        return { name: "macOS", apiName: "mac", arch };
      }
      case UserOS.LINUX:
      case UserOS.UNIX:
        return { name: "Linux", apiName: "linux", arch };
      case UserOS.WIN:
        return { name: "Windows", apiName: "windows", arch };
      default:
        return { name: "", apiName: "", arch };
    }
  }, [userOS]);
  const binary = useFetchLatestForOS(true, latestLTS, apiName, arch);

  return (
    <div className="flex w-full flex-col gap-4">
      <Link
        href={
          binary?.link
            ? {
                pathname: "/download",
                query: { link: binary.link, vendor: "Adoptium" },
              }
            : "/temurin/releases"
        }
        className="group flex w-full items-center justify-between gap-3 rounded-xl bg-pink px-5 py-4 font-semibold text-white shadow-lg shadow-pink/15 transition-colors hover:bg-[#df0b54] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-white"
        onClick={() => {
          if (binary?.link) {
            sendDownloadEvent({
              link: binary.link,
              os: apiName,
              arch,
              pkg_type: binary.installer_link ? "installer" : "archive",
              version: String(latestLTS),
              vendor: "Adoptium",
            });
          }
        }}
      >
        <span className="flex min-w-0 items-center gap-3">
          <span className="shrink-0" aria-hidden="true">
            {name ? <OSIcon os={userOS} /> : <FiDownload size={24} />}
          </span>
          <span className="text-base sm:text-lg">
            {t("download-temurin-button")}
          </span>
        </span>
        <FiDownload className="shrink-0" size={20} aria-hidden="true" />
      </Link>
      <div className="flex flex-wrap items-center justify-between gap-3 text-xs text-grey">
        <span className="font-mono">
          {`JDK ${latestLTS} LTS${name ? ` / ${name} / ${arch}` : ""}`}
        </span>
        <Link
          href="/temurin/releases"
          className="inline-flex items-center gap-1.5 text-white hover:text-[#ff91b7] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
        >
          <span>{t("other-downloads")}</span>
          <FiArrowRight aria-hidden="true" />
        </Link>
      </div>
    </div>
  );
};

export default DownloadButton;
